CREATE FUNCTION public.fn_log_products_changes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_operation VARCHAR(10);
    v_desc TEXT;
BEGIN
    IF (TG_OP = 'INSERT') THEN
        v_operation := 'Create';
        v_desc := 'Se creó el producto: ' || NEW.name || ' (SKU: ' || NEW.sku || ')';
    ELSIF (TG_OP = 'UPDATE') THEN
        v_operation := 'Update';
        v_desc := 'Se actualizó el producto ID: ' || OLD.id || ' (Nombre: ' || OLD.name || ')';
    ELSIF (TG_OP = 'DELETE') THEN
        v_operation := 'Delete';
        v_desc := 'Se eliminó el producto ID: ' || OLD.id || ' (Nombre: ' || OLD.name || ')';
    END IF;

    VALUES ('tb_products', v_operation, CURRENT_USER, v_desc, TRUE);

    IF (TG_OP = 'DELETE') THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_log_products_changes() OWNER TO "mario.banda";

