CREATE VIEW public.vw_trazabilidad_productos AS
 SELECT p.id,
    p.sku,
    p.name,
    b.db_user AS inserted_by,
    COALESCE(b.client_ip, '127.0.0.1'::character varying) AS client_ip,
    COALESCE(string_agg(DISTINCT (re.role_name)::text, ', '::text), 'Sin rol'::text) AS roles,
    b.table_description,
    b.operation_date
   FROM ((public.tb_products p
     JOIN public.tb_logs b ON ((((b.table_name)::text = 'tb_products'::text) AND ((b.table_operation)::text = 'Create'::text) AND ((b.table_description ~~ concat('%', p.sku, '%')) OR (b.table_description ~~ concat('%', p.name, '%')) OR (b.table_description ~~ concat('%ID: ', p.id, '%'))))))
     LEFT JOIN ( SELECT u.rolname AS user_name,
            r.rolname AS role_name
           FROM ((pg_auth_members m
             JOIN pg_roles r ON ((m.roleid = r.oid)))
             JOIN pg_roles u ON ((m.member = u.oid)))) re ON ((re.user_name = split_part((b.db_user)::text, '@'::text, 1))))
  GROUP BY p.id, p.sku, p.name, b.db_user, b.client_ip, b.table_description, b.operation_date;


