   FROM ((public.tb_users u
     JOIN public.tb_logs b ON (((b.table_description ~~ concat('%', u.nick, '%')) AND (b.table_description ~~ concat('%', u.email, '%')))))
     LEFT JOIN ( SELECT u_1.rolname AS user_name,
            r.rolname AS role_name
           FROM ((pg_auth_members m
             JOIN pg_roles r ON ((m.roleid = r.oid)))
             JOIN pg_roles u_1 ON ((m.member = u_1.oid)))) re ON ((re.user_name = split_part((b.db_user)::text, '@'::text, 1))))
  WHERE (((b.table_operation)::text = 'Create'::text) AND ((b.table_name)::text = 'tb_users'::text))
  GROUP BY u.nick, u.email, b.db_user, b.client_ip, b.table_description, b.operation_date
  ORDER BY b.operation_date;


